import{_ as n,l as i,o as a,c as s,v as t,p as l,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"类型健全性","description":"","frontmatter":{"title":"类型健全性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/type-soundness.md","filePath":"cs/type-soundness.md","lastUpdated":1789023840000}'),h={name:"cs/type-soundness.md"};function u(_,e,E,m,A,B){const o=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="类型健全性" tabindex="-1">类型健全性 <a class="header-anchor" href="#类型健全性" aria-label="Permalink to &quot;类型健全性&quot;">​</a></h1><div class="epigraph"><p>进展：良型项不是卡住的非值。保持：一步归约仍良型。合起来：良型程序不会达到「无法再走且不是值」的状态。</p><footer>—— 据 Wright and Felleisen, A Syntactic Approach to Type Soundness, 1994；Pierce TAPL 第 8 章；Milner, 1978 整理</footer></div><p>上一课<a href="/cs/gradual-typing">渐进类型</a>靠运行时强制补洞。缺口是把本单元各系统的承诺收成<strong>定理形状</strong>：健全性。主干类型检查课是算法；本课是「算法在证明什么」。不重推 STLC 全部规则，只钉进展+保持，以及失败模式（未定义行为、<code>unsafe</code>、不健全渐进）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「不会出错」含糊。Wright–Felleisen：在操作语义上证。卡住：非值且无规则可应用（对 STLC 而言如把整数当函数用）。良型排除卡住。缺口是<strong>这两个引理</strong>，不是词法。</p><p>反例：C 的类型系统对缓冲区越界不承诺；Java 对 <code>null</code> 有例外——可把例外当定义的归约，仍「健全」但有陷阱。后课 Option 专门收空。</p><h3 id="健全不是完备" tabindex="-1">健全不是完备 <a class="header-anchor" href="#健全不是完备" aria-label="Permalink to &quot;健全不是完备&quot;">​</a></h3><p>健全：能型则行为遵守。完备：该能型的都能型。HM 对核心 Mini-ML 有主类型；加特设重载后常不完备。不要把二者当一句。</p><p><span class="marginnote">Wright–Felleisen 1994。Milner 的「well-typed programs cannot go wrong」。Pierce TAPL 把进展保持当标准作业。本课不证强规范化（STLC 另有），只点名它更强。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先定值与一步 \\(\\to\\)。证保持：对推导归纳。证进展：对推导归纳，应用情形用保持保证左件是 λ。加引用后须加存储分型。加并发须改「出错」定义（数据竞争可在模型里当未定义）。</p>',11)),(a(),l(c,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WT%5B%22%CE%93%20%E2%8A%A2%20t%20%3A%20%CF%84%22%5D%20--%3E%20PRG%5B%22%E8%BF%9B%E5%B1%95%EF%BC%9A%E5%8F%AF%E8%B5%B0%E6%88%96%E4%B8%BA%E5%80%BC%22%5D%0A%20%20WT%20--%3E%20PRE%5B%22%E4%BF%9D%E6%8C%81%EF%BC%9A%E4%B8%80%E6%AD%A5%E4%BB%8D%E8%89%AF%E5%9E%8B%22%5D%0A%20%20PRG%20--%3E%20SF%5B%22%E4%B8%8D%E5%8D%A1%E4%BD%8F%22%5D%0A%20%20PRE%20--%3E%20SF%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与线性、借用：进展的「值」包含「不能再使用已移动的变量」——那些程序根本不井型。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>语义里若把越界当任意行为（C UB），则没有「卡住」可证，优化可把井型源程序变成任何东西——<a href="/cs/undefined-behavior-opt">未定义行为与优化</a> 再展开。健全性定理必须先钉语言的对错状态。</p><p>渐进：强制失败是定义的归约（blame），仍可健全。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写并发内存模型全文。后课默认：健全 = 进展+保持（相对给定语义）。下一课把语义本身讲清：操作语义。</p><p>也不把测试覆盖当健全性证明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>进展+保持 ⇒ 良型不卡住（相对所选语义）。</li><li>例外可编进语义；UB 则定理空洞。</li><li>健全≠完备。</li><li>出处：Wright and Felleisen, 1994；Pierce TAPL；Milner, 1978。</li></ul>',9))])}const P=n(h,[["render",u]]);export{T as __pageData,P as default};
